<script setup>
import { computed, ref } from 'vue'
import { groupOutstandingOrders } from '../lib/manage-summary'
import { formatVNDate, todayInVN } from '../lib/date'
import { AppButton, Spinner } from './ui'
const props = defineProps({ orders: { type:Array, default:()=>[] }, period:String, loading:Boolean, error:String, hasMore:Boolean, totalCount:Number, stale:Boolean, menuId:String })
const emit = defineEmits(['period-change','load-more','open-menu','retry'])
const scopedOrders = computed(() => props.menuId ? props.orders.filter(order=>order.menu?.id===props.menuId) : props.orders)
const todayGroups = computed(() => groupOutstandingOrders(scopedOrders.value.filter(order=>order.menu?.menu_date===todayInVN())))
const olderGroups = computed(() => groupOutstandingOrders(scopedOrders.value.filter(order=>order.menu?.menu_date<todayInVN())))
const amountOf = groups => groups.reduce((sum,group)=>sum+group.knownTotal,0)
const unknownOf = groups => groups.reduce((sum,group)=>sum+group.unknownAmountCount,0)
const countOf = groups => groups.reduce((sum,group)=>sum+group.count,0)
function age(date) { return Math.floor((Date.parse(todayInVN()+'T00:00:00Z')-Date.parse(date+'T00:00:00Z'))/86400000) }
function ageLabel(date) { const days=age(date); return days<0 ? 'Chưa tới ngày' : days===0 ? 'Hôm nay' : days>=90 ? '90+ ngày' : days+' ngày' }
const search = ref(''), sort = ref('oldest')
const groups = computed(() => groupOutstandingOrders(props.menuId ? props.orders.filter(order=>order.menu?.id===props.menuId) : props.orders).filter(group => group.name.toLocaleLowerCase('vi').includes(search.value.toLocaleLowerCase('vi'))).sort((a,b) => sort.value === 'amount' ? b.knownTotal - a.knownTotal : a.oldestDate.localeCompare(b.oldestDate)))
const knownTotal = computed(() => groups.value.reduce((sum, group) => sum + group.knownTotal, 0))
const unknown = computed(() => groups.value.reduce((sum, group) => sum + group.unknownAmountCount, 0))
const money = value => value == null ? 'Chưa có giá' : new Intl.NumberFormat('vi-VN').format(value) + 'đ'
</script>
<template><section class="ledger-workspace"><h2>Tiền chưa thu</h2><p class="meta">Xem theo người và ngày đặt.</p><div class="ledger-summary"><div class="ledger-stat"><span>Hôm nay · {{ countOf(todayGroups) }} khoản đã tải</span><strong>{{ money(amountOf(todayGroups)) }}</strong><small v-if="unknownOf(todayGroups)">Đã biết · {{ unknownOf(todayGroups) }} khoản chưa có giá</small></div><div class="ledger-stat"><span>Các ngày trước · {{ countOf(olderGroups) }} khoản đã tải</span><strong>{{ money(amountOf(olderGroups)) }}</strong><small v-if="unknownOf(olderGroups)">Đã biết · {{ unknownOf(olderGroups) }} khoản chưa có giá</small></div></div><div class="ledger-periods" role="group" aria-label="Khoảng thời gian chưa trả"><AppButton v-for="option in [{id:'today',name:'Hôm nay'},{id:'recent',name:'30 ngày trước'},{id:'older',name:'Cũ hơn 30 ngày'},{id:'all',name:'Tất cả'}]" :key="option.id" variant="ghost" :aria-pressed="period===option.id" @click="emit('period-change',option.id)">{{ option.name }}</AppButton></div><div class="ledger-filters"><label class="field">Tìm người<input v-model="search" type="search" class="input" /></label><label class="field">Sắp xếp<select v-model="sort" class="input"><option value="oldest">Bữa cũ nhất</option><option value="amount">Số tiền đã biết</option></select></label></div><p v-if="menuId" class="meta">Đang xem các khoản của menu trong đường dẫn. <AppButton variant="ghost" to="/dashboard">Tất cả menu</AppButton></p><p v-if="stale" class="meta" role="status">Đang giữ kết quả của khoảng trước cho đến khi tải được khoảng mới.</p><p class="load-scope" role="status">{{ loading ? 'Đang cập nhật · ' : '' }}{{ orders.length }}{{ totalCount!=null ? ' / '+totalCount : '' }} khoản đã tải{{ hasMore ? ' · Số liệu, tìm kiếm và sắp xếp theo phần đã tải' : '' }}.</p><p v-if="error" class="alert" role="alert">{{ error }} <AppButton variant="ghost" @click="emit('retry')">Thử lại</AppButton></p><Spinner v-if="loading && !orders.length" /><section v-else class="card ledger-card"><div class="ledger-heading"><h3>{{ groups.length }} người · {{ groups.reduce((sum,group)=>sum+group.count,0) }} khoản</h3><strong>{{ money(knownTotal) }}{{ unknown ? ' đã biết' : '' }}</strong></div><p v-if="!groups.length" class="empty-ledger">Không có khoản chưa thu trong khoảng này.</p><details v-for="group in groups" :key="group.userId" class="ledger-group"><summary><div><strong>{{ group.name }}</strong><p class="meta">{{ group.count }} khoản · Bữa cũ nhất {{ formatVNDate(group.oldestDate) }}<span v-if="age(group.oldestDate)>=90"> · Có khoản 90+ ngày</span><span v-if="group.unknownAmountCount"> · {{ group.unknownAmountCount }} khoản chưa có giá</span></p></div><strong class="group-total">{{ money(group.knownTotal) }}{{ group.unknownAmountCount ? ' đã biết' : '' }} <span aria-hidden="true">⌄</span></strong></summary><article v-for="order in group.entries" :key="order.id" class="ledger-entry"><div><strong>{{ formatVNDate(order.menu?.menu_date) }} · {{ order.menu?.restaurant?.name || order.menu?.title }}</strong><p class="order-lines">{{ order.item_text }}</p><p v-if="order.note" class="meta">{{ order.note }}</p><span class="age-badge" :class="{old:age(order.menu?.menu_date)>=90}">{{ ageLabel(order.menu?.menu_date) }}</span></div><div class="entry-end"><strong>{{ money(order.amount) }}</strong><AppButton variant="ghost" @click="emit('open-menu',order.menu.id)">Mở menu</AppButton></div></article></details><div class="ledger-footer"><span>Tổng {{ hasMore ? 'phần đã tải' : 'khoản hiển thị' }}</span><strong>{{ money(knownTotal) }}</strong></div><p v-if="unknown" class="meta">{{ unknown }} khoản chưa có giá</p></section><AppButton v-if="hasMore && !stale" class="load-more" variant="ghost" :loading="loading" @click="emit('load-more')">Tải tiếp</AppButton><p class="ledger-note">Trạng thái do mỗi người tự xác nhận trong app. Các khoản cũ vẫn được giữ.</p></section></template>
<style scoped>
.ledger-workspace>h2{font-size:22px;margin:0}.ledger-workspace>.meta{font-size:13px;margin-top:7px}.ledger-summary{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin:23px 0}.ledger-stat{padding:18px;border:1px solid var(--line);border-radius:13px;background:var(--card);min-width:0}.ledger-stat span,.ledger-stat small{font-size:12px;color:var(--muted);line-height:1.6}.ledger-stat small{display:block}.ledger-stat strong{font-size:28px;line-height:1.3;display:block;margin-top:6px;overflow-wrap:anywhere}.ledger-periods{display:flex;gap:8px;flex-wrap:wrap;margin:18px 0}.ledger-workspace :deep(.btn){font-size:13px;padding:10px 13px;border-radius:12px}.ledger-periods :deep([aria-pressed=true]){border-color:var(--ink);font-weight:700;background:var(--bg-tint)}.ledger-filters{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,.5fr);gap:14px;margin-bottom:14px}.ledger-filters .field{font-size:13px}.ledger-filters .input{min-height:46px;font-size:14px;border-radius:12px}.load-scope{font-size:12px;color:var(--muted);margin:14px 0}.ledger-card{padding:22px}.ledger-heading{display:flex;justify-content:space-between;align-items:center;gap:13px;flex-wrap:wrap;margin-bottom:10px}.ledger-heading h3{font-size:20px;margin:0}.ledger-heading>strong{font-size:16px}.ledger-group{border-top:1px solid var(--line)}.ledger-group:first-of-type{border-top:0}.ledger-group summary{min-height:68px;cursor:pointer;list-style:none;display:flex;align-items:center;justify-content:space-between;gap:12px;font-size:15px}.ledger-group summary::-webkit-details-marker{display:none}.ledger-group summary>.group-total{flex:none;text-align:right;font-size:15px}.ledger-group .meta{font-size:12px;line-height:1.6;margin:5px 0}.ledger-entry{padding:13px 0 13px 18px;border-top:1px solid var(--line);display:flex;justify-content:space-between;gap:15px}.ledger-entry>div{min-width:0}.ledger-entry>div>strong{font-size:13px}.ledger-entry p{font-size:12px;margin:5px 0}.entry-end{text-align:right;flex-shrink:0;display:grid;justify-items:end;align-content:start;gap:9px}.entry-end>strong{font-size:14px!important}.entry-end :deep(.btn){font-size:12px}.age-badge{display:inline-flex;padding:4px 8px;border-radius:7px;font-size:11px;font-weight:650;background:var(--bg-tint);color:var(--muted);white-space:nowrap}.age-badge.old{background:var(--unpaid-bg);color:var(--unpaid-ink)}.ledger-footer{display:flex;justify-content:space-between;gap:13px;border-top:1px solid var(--line);margin-top:16px;padding-top:15px;font-weight:750;font-size:14px}.ledger-note{font-size:12px;color:var(--muted);margin-top:16px;line-height:1.7}.order-lines{white-space:pre-line;overflow-wrap:anywhere}.load-more{margin-top:16px}.empty-ledger{padding:28px 12px;text-align:center;color:var(--muted)}@media(max-width:640px){.ledger-summary{gap:9px}.ledger-stat{padding:14px}.ledger-stat strong{font-size:25px}.ledger-periods{gap:7px}.ledger-periods :deep(.btn){font-size:12px;padding:9px 10px}.ledger-card{padding:19px}.ledger-filters{grid-template-columns:1fr}.ledger-filters .input{font-size:16px}.ledger-group summary{gap:8px;flex-wrap:wrap;padding:13px 0}.ledger-entry{padding-left:0}.ledger-entry .entry-end{flex-shrink:1}.ledger-entry>div:first-child{flex:1}}
</style>
